{"explanation":"Maintain an LRU resident cache, durable map, lifetime versions, and the set of emitted flush versions. Writes dirty entries; acknowledgments persist only the currently flushed version. Reads promote durable values only when a clean slot is available.","mapping":"Cache entries map keys to value, version, and dirty state; order is oldest-to-newest. Durable stores acknowledged values. Versions survive eviction, and emitted flush versions authorize matching acknowledgments.","assumptions":"Event values are finite JSON values and keys are strings. Unknown event types are treated as no-ops. The supplied slot count is a positive integer.","applies":"function applies(input){return !!input&&!!input.config&&Array.isArray(input.events)&&input.config.slots>=1}","holds":"function holds(input,output){if(!Array.isArray(output))return false;for(const o of output){if(!o||!Array.isArray(o.cached)||!Array.isArray(o.dirty)||!Array.isArray(o.flush)||!o.durable||o.cached.some(k=>typeof k!=="string"||k.includes("__changed")))return false}return true}","program":"function solve({config,state,event}){
  let s=state||{c:{},o:[],d:{},v:{},f:{}};
  let t=event.type,k=event.key,status="ignored",value=null,flush=[];
  const has=(o,x)=>Object.prototype.hasOwnProperty.call(o,x);
  const touch=x=>{let i=s.o.indexOf(x);if(i>=0)s.o.splice(i,1);s.o.push(x)};
  const cleanSlot=()=>{for(let i=0;i<s.o.length;i++){let x=s.o[i];if(!s.c[x].dirty){s.o.splice(i,1);delete s.c[x];return true}}return false};
  if(t==="write"){
    let n=(s.v[k]||0)+1;s.v[k]=n;
    if(has(s.c,k)){s.c[k]={v:event.value,n:n,dirty:true};touch(k);status="written"}
    else if(s.o.length<config.slots||cleanSlot()){s.c[k]={v:event.value,n:n,dirty:true};s.o.push(k);status="written"}
    else status="blocked";
  }else if(t==="read"){
    if(has(s.c,k)){value=s.c[k].v;touch(k);status="hit"}
    else if(has(s.d,k)){value=s.d[k];if(s.o.length<config.slots||cleanSlot()){s.c[k]={v:value,n:s.v[k]||0,dirty:false};s.o.push(k);status="durable"}else status="durable"}
    else status="miss";
  }else if(t==="flush"){
    if(has(s.c,k)&&s.c[k].dirty){let e=s.c[k];flush=[{key:k,value:e.v,version:e.n}];if(!s.f[k])s.f[k]={};s.f[k][e.n]=true;status="flushed"}
  }else if(t==="ack"){
    if(has(s.c,k)){let e=s.c[k];if(e.dirty&&event.version===e.n&&s.f[k]&&s.f[k][e.n]){s.d[k]=e.v;e.dirty=false;status="persisted"}}
  }else if(t==="evict"){
    if(!has(s.c,k))status="missing";else if(s.c[k].dirty)status="blocked";else{delete s.c[k];s.o.splice(s.o.indexOf(k),1);status="evicted"}
  }
  let dirty=s.o.filter(x=>s.c[x].dirty).sort();
  return {state:s,output:{status:status,value:value,flush:flush,cached:s.o.slice(),dirty:dirty,durable:Object.assign({},s.d)}};
}"}
